/// Triangulate a polygon given as a list of rings (outer ring first, holes after)
/// and return a flat list of triangle vertex indices into the concatenated rings.
pub fn earcut(points: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut earcut = Earcut::new();
    earcut.run(points);
    earcut.indices
